define({"topics":[{"title":"MR–PET image alignment volumetric quality control (VQC) calibration (MP24\/MP26)","shortdesc":"<p class=\"shortdesc\">When the PET\/MR insert is removed or there is any mechanical alignment, do an MR-PET image alignment VQC calibration. This calibration checks for the correct relationship between magnetic resonance (MR) imaging and positron emission tomography (PET) imaging.<\/p>","href":"t_PETMRImageAlignmentVQCCalibration_MP24_MP26.html","attributes":{"data-id":"id_2041182"},"menu":{"hasChildren":false},"tocID":"id_2041182-d46e20789","topics":[]},{"title":"MR–PET image alignment volumetric quality control (VQC) calibration (MR30)","shortdesc":"<p class=\"shortdesc\">When the PET\/MR insert is removed or there is any mechanical alignment, do an MR-PET image alignment VQC calibration. This calibration checks for the correct relationship between magnetic resonance (MR) imaging and positron emission tomography (PET) imaging.<\/p>","href":"t_PETMR-Image-Alignment-VQC-Calibration_MP30.html","attributes":{"data-id":"id_2041183"},"menu":{"hasChildren":false},"tocID":"id_2041183-d46e20894","topics":[]}]});